{
  "morphology_wrong_forms": [
    {
      "form": "盛り上がりまする",
      "explanation": "Incorrect polite archaic ending. The correct polite non-past form is 盛り上がります."
    },
    {
      "form": "盛り合る",
      "explanation": "Incorrect stem reduction. The verb is a godan verb ending in -ru (盛り上がる), so the correct dictionary form retains the 'agaru' portion."
    },
    {
      "form": "盛り上がったる",
      "explanation": "Incorrect auxiliary combination. 'Taru' is an archaic attributive/perfective suffix not used to form the standard past tense of godan verbs (which uses 盛り上がった)."
    }
  ],
  "collocation_distractors": [
    {
      "collocate": "を決定する",
      "explanation": "盛り上がる (to get excited, to swell) is intransitive and typically takes particles like が or に, not the direct object marker を with 'to decide'."
    },
    {
      "collocate": "を開発する",
      "explanation": "Development (開発する) requires a direct object to be built or engineered, which does not semantically match an intransitive state of excitement or rising."
    },
    {
      "collocate": "を乾燥する",
      "explanation": "Drying something (乾燥する) is a transitive physical action, whereas 盛り上がる describes an abstract rise in atmosphere or a physical bulge/mound."
    }
  ],
  "collocation_wrong_collocate": "を解決する",
  "cloze_distractors": [
    {
      "option": "盛り下がる",
      "reason": "This is an antonym meaning 'to die down' or 'to deflate', which contradicts a positive party or conversation getting lively."
    },
    {
      "option": "盛り付ける",
      "reason": "This means 'to dish up food', which shares the kanji 盛 but has a completely different meaning and transitive valency."
    },
    {
      "option": "埋める",
      "reason": "This means 'to bury' or 'to fill', which does not fit the intransitive dynamic of an event or mood rising."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は会議の資料をきれいに盛り上がった。",
      "reason": "Using 盛り上がる intransitively for organizing or preparing physical documents is incorrect; a transitive verb like まとめた or 準備した is needed."
    },
    {
      "sentence": "昨日、新しいプロジェクトを盛り上がった。",
      "reason": "盛り上がる is an intransitive verb and cannot take the direct object marker を to mean 'excited a project'."
    },
    {
      "sentence": "コップのジュースを机の上に盛り上がった。",
      "reason": "Liquids in a cup cannot use 盛り上がる in this context; it describes mounds or swelling, not liquid volume or placement."
    }
  ],
  "spot_incorrect": {
    "sentence": "パーティーの雰囲気がとても盛り下げた。",
    "planted_error": "盛り下げた",
    "error_description": "盛り下げる is rarely used transitively this way; if describing a mood dying down, the intransitive 盛り下がった or 盛り上がらなかった is grammatically correct.",
    "corrected_version": "パーティーの雰囲気がとても盛り上がった。"
  },
  "word_family_fake_forms": [
    {
      "form": "盛り上がりみ",
      "explanation": "Plausible-looking nominalization suffix '-mi' attached incorrectly to the stem of a verb."
    },
    {
      "form": "盛り上がりる",
      "explanation": "Incorrectly treats the nominalized/masu-stem form 盛り上がり as a base for another godan verb."
    },
    {
      "form": "盛り合さる",
      "explanation": "Fake intransitive-transitive pairing suffix alteration (-saru instead of -garu)."
    }
  ],
  "particle_candidates": [
    "が",
    "を",
    "に",
    "で"
  ]
}
